INSERT INTO `exam_attempts` VALUES (1,'erneste','0789245524',7,20,'{\"question_16\":\"C\",\"question_32\":\"B\",\"question_38\":\"B\",\"question_48\":\"B\",\"question_108\":\"D\",\"question_109\":\"D\",\"question_126\":\"B\",\"question_130\":\"D\",\"question_135\":\"C\",\"question_138\":\"D\",\"question_155\":\"D\",\"question_167\":\"A\",\"question_168\":\"C\",\"question_205\":\"B\"}','[{\"id\":138,\"correct_option\":\"D\",\"question\":\"Iki cyapa cyerekana :\",\"option_a\":\"ifungana ry’umuhanda\",\"option_b\":\"ifungana ry’umuhanda n’akayira gasatira umuhanda i bumoso\",\"option_c\":\"umuhanda utaringaniye\",\"option_d\":\"nta gisubizo cy’ukuri kirimo\",\"image_path\":\"SA_road_sign_-_Road_narrows_on_the_right.svg.png\"},{\"id\":205,\"correct_option\":\"C\",\"question\":\"Inkombe z’inzira nyabagendwa cyangwa z’umuhanda zishobora kugaragazwa n’ibikoresho ngarurarumuri. Ibyo bikoresho bigomba gushyirwaho ku buryo abagenzi babibona ku buryo bukurikira:\",\"option_a\":\"babona iburyo bwabo ibyibara ritukura cyangwa ibisa n’icunga rihishije\",\"option_b\":\"ibumoso babona iby’ibara ryera\",\"option_c\":\"A na B ni ibisubizo by’ukuri\",\"option_d\":\"nta gisubizo cy’ukuri kirimo\",\"image_path\":null},{\"id\":135,\"correct_option\":\"C\",\"question\":\"Iki cyapa kigizwe:\",\"option_a\":\"ishusho mpandeshatu ,ubuso ubururu\",\"option_b\":\"ishusho mpandeshatu,ubuso umukara\",\"option_c\":\"ishusho mpandeshatu,ubuso umweru\",\"option_d\":\"nta gisubizo cy’ukuri\",\"image_path\":\"external-road-traffic-road-signs-those-icons-lineal-those-icons-1.jpg\"},{\"id\":181,\"correct_option\":\"B\",\"question\":\"Ibinyabiziga bikurikira bigomba kugira icyerekana umuvuduko kiri aho umuyobozi areba neza kandi kigahora kitabwaho kugirango kigume gukora neza:\",\"option_a\":\"ibinyabiziga bifite umuvuduko nibura wa km 60 mu isaha\",\"option_b\":\"ibinyabiziga bishobora kurenza km 40 mu isaha\",\"option_c\":\"ibinyabiziga bishobora kurenza km 30 mu isaha\",\"option_d\":\"ibinyabiziga bishobora kurenza km 25 mu isaha\",\"image_path\":null},{\"id\":38,\"correct_option\":\"C\",\"question\":\"Umuyobozi w’ikinyabizaga uri kugendera mu muhanda w’ibyerekezo bibiri nuruhe ruhande rw’umuhanda agomba gukoresha ?\",\"option_a\":\"uruhande rw’ibumoso bw’umuhanda uretse igihe atawaye imashini zihinga cyangwa zikoreshwa indi mirimo\",\"option_b\":\"Mu gice cy\'umuhanda yumva ashaka\",\"option_c\":\"Mu gice cy’iburyo bw’umuhanda uretse igihe ashaka kunyuranaho cyangwa gukata ibumoso\",\"option_d\":\" Ku ruhande rw’ibumoso bw’umuhanda\",\"image_path\":\"\"},{\"id\":44,\"correct_option\":\"C\",\"question\":\"Iyo nta mategeko awugabanya by’umwihariko, umuvuduko ntarengwa ku modoka zikoreshwa nk’amavatiri y’ifasi cyangwa amatagisi zifite uburemere bwemewe butarenga kilogarama 3500 ni:\\r\\n\",\"option_a\":\"Km 60 mu isaha\",\"option_b\":\"Km 40 mu isaha\",\"option_c\":\"Km 75 mu isaha\",\"option_d\":\"Km20 mu isaha\",\"image_path\":null},{\"id\":155,\"correct_option\":\"D\",\"question\":\"Iki cyapa gisobanura iki ?\",\"option_a\":\"Umuhanda urombereje w’ibice byinshi ibumoso\",\"option_b\":\"Umuhanda uyoborejwe i bumoso\",\"option_c\":\"Ibinyabiziga biturutse iburyo bifite uburenganzira bwo gutambuka mbere\",\"option_d\":\"Kata i bumoso gusa\",\"image_path\":\"Mauritius_Road_Signs_-_Mandatory_Sign_-_Left_turn_only.svg.png\"},{\"id\":167,\"correct_option\":\"A\",\"question\":\"Ni iyihe feri ituma imodoka igenda buhoro kandi igahagarara ku buryo bwizewe bubangutse kandi nyabwo, uko imodoka yaba yikoreye kose yaba igeze ahacuramye cyangwa ahaterera:\",\"option_a\":\"Feri y’urugendo\",\"option_b\":\"Feri yo gutabara\",\"option_c\":\"Feri yo guhagarara umwanya munini\",\"option_d\":\"Nta gisubizo cy’ukuri kirimo\",\"image_path\":null},{\"id\":234,\"correct_option\":\"D\",\"question\":\"Ibyapa byerekana icyago cyidahoraho kandi bigenewe kwerekana aho bagana cyangwa aho berekeza umuhanda nk’igihe cy’impanuka cyangwa hari imirimo ikorwa mu muhanda birangwa n’amabara akurikira:\",\"option_a\":\"umweru n’umukara\",\"option_b\":\"umweru n’umuhondo\",\"option_c\":\"ubuso bw’umweru gusa\",\"option_d\":\"nta gisubizo cy’ukuri kirimo\",\"image_path\":\"\"},{\"id\":32,\"correct_option\":\"A\",\"question\":\"N’iyihe myifatire myiza wagira ugeze aho abana bari hafi y’inzira nyabagendwa?\",\"option_a\":\"Itonde , witegereze ni biba ngongwa ubaburire unitegura kuba wahagarara.\",\"option_b\":\"Ihute urenge aho abo bana bari\",\"option_c\":\"Komeza ugume ku muvuduko munini\",\"option_d\":\"Komeza ugendere kuruhande rw’iburyo\",\"image_path\":\"sign1.png\"},{\"id\":48,\"correct_option\":\"D\",\"question\":\"Icyapa kivuga gutambuka mbere\\r\\ny’ibinyabiziga biturutse imbere gifite amabara\\r\\nakurikira\",\"option_a\":\"Ubuso ni umweru\",\"option_b\":\"Ikirango ni umutuku n’umukara\",\"option_c\":\"Ikirango ni umweru n’umukara\",\"option_d\":\"Nta gisubizo cy’ukuri kirimo\",\"image_path\":null},{\"id\":16,\"correct_option\":\"C\",\"question\":\"Nibura ikinyabiziga gitegetswe kugira\\r\\nuduhanagurakirahure tungahe:\",\"option_a\":\"2\",\"option_b\":\"3\",\"option_c\":\"1\",\"option_d\":\"Nta gisubizo cy’ukuri kirimo\",\"image_path\":null},{\"id\":109,\"correct_option\":\"A\",\"question\":\"Umuyobozi w’ikinyabiziga ugendera inyuma y’ikinyabaziga gitwara abagenzi gihagaze gikuramo cyangwa gishyiramo abagenzi agomba :\\r\\n\",\"option_a\":\"kunyuranaho ibumoso\",\"option_b\":\"gutegereza yihanganye\",\"option_c\":\"a na b ni ibisubizo by’ukuri\",\"option_d\":\"nta gisubizo cy’ukuri kirimo\",\"image_path\":null},{\"id\":108,\"correct_option\":\"B\",\"question\":\"Umuyobozi w’ikinyabiziga yakwitondera iki mbere yuko y’injira munzira banyuramo bazengurutse ?\\r\\n\",\"option_a\":\"ibinyabiziga bimuturuka inyuma umuvuduko bifite n’uburyo bimwegereye\",\"option_b\":\"ibinyabiziga biturutse ibumoso bwe n’umuvuduko bifite n’intera iri hagati ye nabyo\",\"option_c\":\"ibinyabiziga biturutse iburyo n’umuvuduko bifite ni intera iri hagati ye nabyo\",\"option_d\":